<?php
function save_upload($field,$dir,$types=['image/jpeg','image/png','image/webp','application/pdf'],$max=5242880){if(empty($_FILES[$field])||!is_uploaded_file($_FILES[$field]['tmp_name']))throw new RuntimeException('No valid upload received');$f=$_FILES[$field];if($f['error']!==UPLOAD_ERR_OK||$f['size']>$max)throw new RuntimeException('File is too large or upload failed');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);if(!in_array($mime,$types,true))throw new RuntimeException('File type is not allowed');$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp','application/pdf'=>'pdf'][$mime];$dir=__DIR__.'/uploads/'.$dir;if(!is_dir($dir)&&!mkdir($dir,0755,true))throw new RuntimeException('Upload folder unavailable');$name=bin2hex(random_bytes(16)).'.'.$ext;$target=$dir.'/'.$name;if(!move_uploaded_file($f['tmp_name'],$target))throw new RuntimeException('Could not save upload');return 'backend/uploads/'.str_replace('\\','/',substr($target,strlen(__DIR__.'/uploads/')));}
